<template><section class="content-composer"><button @click="show=!show">{{show?'收起':kind==='guide'?'分享租房经验':'评价这次沟通体验'}}</button><form v-if="show" @submit.prevent="submit"><template v-if="kind==='guide'"><input v-model.trim="title" placeholder="攻略标题" maxlength="200" required/><select v-model="category"><option>看房技巧</option><option>合同知识</option><option>搬家经验</option><option>区域推荐</option></select></template><label v-else>评分<select v-model.number="score"><option v-for="n in 5" :key="n" :value="n">{{n}}分</option></select></label><textarea v-model.trim="content" :maxlength="kind==='guide'?30000:2000" rows="5" required :placeholder="kind==='guide'?'写下你的经验':'请基于真实沟通描述体验，未实际入住请勿描述为入住评价'"/><label v-if="kind==='review'"><input type="checkbox" v-model="anonymous"/>匿名展示</label><p>提交后需要平台审核；处理意见可在“平台通知与办理进度”查看。</p><button :disabled="busy">{{busy?'提交中…':'提交审核'}}</button></form><p v-if="message" role="status">{{message}}</p></section></template>
<script setup>
import {ref} from 'vue'
import request from '../api/index'
const props=defineProps({kind:{type:String,default:'guide'},houseId:Number,landlordId:Number}),show=ref(false),title=ref(''),category=ref('看房技巧'),content=ref(''),score=ref(5),anonymous=ref(false),busy=ref(false),message=ref('')
async function submit(){busy.value=true;message.value='';try{await request.post(props.kind==='guide'?'/guide/publish':'/landlord-review/submit',props.kind==='guide'?{title:title.value,category:category.value,content:content.value}:{houseId:props.houseId,landlordId:props.landlordId,content:content.value,score:score.value,isAnonymous:anonymous.value?1:0});message.value='已提交，等待审核。';content.value='';show.value=false}catch(e){message.value=e.response?.data?.message||e.message}finally{busy.value=false}}
</script>
<style scoped>.content-composer{padding:20px 0;margin-bottom:20px}.content-composer button,.content-composer select,.content-composer textarea,.content-composer input:not([type=checkbox]){padding:11px 15px;border:1px solid var(--jade-line);background:#fffefa;border-radius:4px;color:var(--jade-700)}.content-composer textarea,.content-composer input:not([type=checkbox]){display:block;width:100%;margin:14px 0}.content-composer p{font-size:13px;line-height:1.9;margin:12px 0}.content-composer form{padding:22px;background:#f1f5ed;margin-top:16px}.content-composer label{font-size:13px}</style>
